function loadChannelFeed(channelId, gridElement, fallbackData) {
  if (!gridElement) return;

  const rssUrl = `https://www.youtube.com/feeds/videos.xml?channel_id=${channelId}`;
  const apiUrl = `https://api.rss2json.com/v1/api.json?rss_url=${encodeURIComponent(rssUrl)}`;

  fetch(apiUrl)
    .then(res => res.json())
    .then(data => {
      if (data && data.status === 'ok' && data.items && data.items.length > 0) {
        // Extract top 4 videos
        const videos = data.items.slice(0, 4).map(item => {
          let videoId = '';
          const link = item.link || '';
          const reg = /[?&]v=([^&#]+)/;
          const match = link.match(reg);
          if (match && match[1]) {
            videoId = match[1];
          } else {
            videoId = link.split('/').pop();
          }
          return {
            title: item.title,
            id: videoId,
            pubDate: item.pubDate ? item.pubDate.split(' ')[0] : ''
          };
        });
        renderVideoCards(gridElement, videos);
      } else {
        renderVideoCards(gridElement, fallbackData);
      }
    })
    .catch(err => {
      console.warn("YouTube feed fetch failed, using fallback.", err);
      renderVideoCards(gridElement, fallbackData);
    });
}

function renderVideoCards(gridElement, videos) {
  gridElement.innerHTML = '';
  
  videos.forEach(video => {
    const card = document.createElement('div');
    card.className = 'video-feed-card';
    card.innerHTML = `
      <div class="video-thumbnail-wrapper">
        <img class="video-thumbnail" src="https://img.youtube.com/vi/${video.id}/mqdefault.jpg" alt="${escapeHTML(video.title)}">
        <div class="video-play-overlay">
          <svg style="width: 44px; height: 44px; fill: var(--color-accent); filter: drop-shadow(0 2px 8px rgba(0,0,0,0.3));" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
            <path d="M8 5v14l11-7z"/>
          </svg>
        </div>
      </div>
      <div class="video-feed-info">
        <h4 class="video-feed-title">${escapeHTML(video.title)}</h4>
        <span class="video-feed-date">${video.pubDate ? formatDate(video.pubDate) : ''}</span>
      </div>
    `;
    card.addEventListener('click', () => openVideoModal(video.id));
    gridElement.appendChild(card);
  });
}

function formatDate(dateStr) {
  try {
    const date = new Date(dateStr);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  } catch (e) {
    return dateStr;
  }
}

function createVideoModal() {
  const existingModal = document.getElementById('video-modal');
  if (existingModal) {
    // If it's the old layout structure (doesn't have floating close button directly inside container)
    if (!existingModal.querySelector('.modal-container > #video-modal-close-btn')) {
      existingModal.remove(); // Clean up stale DOM element
    } else {
      return; // Already correct, skip creation
    }
  }

  const modal = document.createElement('div');
  modal.id = 'video-modal';
  modal.className = 'modal-overlay';
  
  // Apply fail-proof inline styles to ensure the overlay is centered and cinematic even if styles are cached
  modal.style.position = 'fixed';
  modal.style.top = '0';
  modal.style.left = '0';
  modal.style.width = '100%';
  modal.style.height = '100%';
  modal.style.backgroundColor = 'rgba(10, 8, 6, 0.9)';
  modal.style.backdropFilter = 'blur(10px)';
  modal.style.webkitBackdropFilter = 'blur(10px)';
  modal.style.zIndex = '3000';
  modal.style.display = 'flex';
  modal.style.alignItems = 'center';
  modal.style.justifyContent = 'center';
  modal.style.opacity = '0';
  modal.style.pointerEvents = 'none';
  modal.style.transition = 'opacity 0.3s ease';

  modal.innerHTML = `
    <div class="modal-container">
      <!-- Floating round close button overlaying the top-right corner of the video -->
      <button id="video-modal-close-btn" style="position: absolute; top: 15px; right: 15px; z-index: 100; background: rgba(0, 0, 0, 0.5); border: 1px solid rgba(255,255,255,0.25); color: #fff; font-size: 24px; width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: background-color 0.2s, transform 0.2s; line-height: 1; padding: 0; box-shadow: 0 2px 8px rgba(0,0,0,0.3);">&times;</button>
      
      <div class="modal-body" style="padding: 0; width: 100%; height: 100%; position: relative; background-color: #000;">
        <iframe id="video-modal-iframe" src="" style="position: absolute; top:0; left:0; width:100%; height:100%; border:0;" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>
      </div>
    </div>
  `;

  document.body.appendChild(modal);

  const closeBtn = modal.querySelector('#video-modal-close-btn');
  closeBtn.addEventListener('click', closeVideoModal);

  // Close button hover animations handled in JS
  closeBtn.addEventListener('mouseenter', () => {
    closeBtn.style.backgroundColor = 'rgba(0, 0, 0, 0.8)';
    closeBtn.style.transform = 'scale(1.08)';
  });
  closeBtn.addEventListener('mouseleave', () => {
    closeBtn.style.backgroundColor = 'rgba(0, 0, 0, 0.5)';
    closeBtn.style.transform = 'scale(1)';
  });

  modal.addEventListener('click', (e) => {
    if (e.target === modal) {
      closeVideoModal();
    }
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modal.style.opacity === '1') {
      closeVideoModal();
    }
  });
}

function openVideoModal(videoId) {
  const modal = document.getElementById('video-modal');
  const iframe = document.getElementById('video-modal-iframe');
  if (modal && iframe) {
    iframe.src = `https://www.youtube.com/embed/${videoId}?autoplay=1`;
    modal.classList.add('active');
    modal.style.opacity = '1';
    modal.style.pointerEvents = 'auto';
    document.body.style.overflow = 'hidden';

    // Force-apply explicit sizing and absolute positioning styles inline to container to bypass any cached CSS stylesheets
    const container = modal.querySelector('.modal-container');
    if (container) {
      container.style.position = 'absolute';
      container.style.top = '50%';
      container.style.left = '50%';
      container.style.transform = 'translate(-50%, -50%) scale(1)';
      container.style.width = '90%';
      container.style.maxWidth = '800px';
      container.style.maxHeight = '80vh';
      container.style.aspectRatio = '16/9';
      container.style.backgroundColor = '#000';
      container.style.borderRadius = '8px';
      container.style.overflow = 'hidden';
      container.style.boxShadow = '0 10px 40px rgba(0,0,0,0.6)';
      container.style.border = '1px solid rgba(255,255,255,0.15)';
      container.style.transition = 'transform 0.3s ease';
      container.style.zIndex = '3100';
    }
  }
}

function closeVideoModal() {
  const modal = document.getElementById('video-modal');
  const iframe = document.getElementById('video-modal-iframe');
  if (modal && iframe) {
    modal.classList.remove('active');
    modal.style.opacity = '0';
    modal.style.pointerEvents = 'none';
    iframe.src = '';
    document.body.style.overflow = '';

    const container = modal.querySelector('.modal-container');
    if (container) {
      container.style.transform = 'translate(-50%, -50%) scale(0.95)';
    }
  }
}

/* ==========================================
   INTERACTIVE GALLERY & LIGHTBOX MODAL
   ========================================== */
function initGallery() {
  const filterButtons = document.querySelectorAll('.gallery-filter-btn');
  const galleryItems = document.querySelectorAll('.gallery-item');
  
  if (filterButtons.length > 0) {
    filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        // Toggle active button
        filterButtons.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        
        const filter = btn.getAttribute('data-filter');
        
        galleryItems.forEach(item => {
          if (filter === 'all' || item.getAttribute('data-category') === filter) {
            item.style.display = 'flex';
            item.style.opacity = '0';
            setTimeout(() => {
              item.style.opacity = '1';
            }, 50);
          } else {
            item.style.display = 'none';
          }
        });
      });
    });
  }

  // Lightbox Modal logic
  const lightboxModal = document.getElementById('lightbox-modal');
  const lightboxImg = document.getElementById('lightbox-img');
  const lightboxCaption = document.getElementById('lightbox-caption');
  const closeBtn = document.getElementById('lightbox-close');

  if (lightboxModal && lightboxImg && closeBtn) {
    galleryItems.forEach(item => {
      const img = item.querySelector('img');
      const captionText = item.querySelector('.gallery-caption-title')?.textContent || '';
      
      if (img) {
        item.style.cursor = 'pointer';
        item.addEventListener('click', () => {
          lightboxImg.src = img.getAttribute('src') || img.src;
          lightboxCaption.textContent = captionText;
          lightboxModal.classList.add('active');
          document.body.style.overflow = 'hidden'; // Lock background scroll
        });
      }
    });

    const closeLightbox = () => {
      lightboxModal.classList.remove('active');
      lightboxImg.src = '';
      document.body.style.overflow = ''; // Unlock background scroll
    };

    closeBtn.addEventListener('click', closeLightbox);
    
    // Close on clicking outside container
    lightboxModal.addEventListener('click', (e) => {
      if (e.target === lightboxModal) {
        closeLightbox();
      }
    });

    // Close on Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && lightboxModal.classList.contains('active')) {
        closeLightbox();
      }
    });
  }
}

/* ==========================================
   DEDICATED SONG DETAIL PAGE LOGIC
   ========================================== */
function openSongPage(songId) {
  const searchInput = document.getElementById('song-search');
  const searchVal = searchInput ? searchInput.value.trim() : '';
  window.location.href = `song.html?id=${songId}&lang=${currentLanguage}&subpart=${currentTamilSubpart}&search=${encodeURIComponent(searchVal)}`;
}

function initSongPage() {
  const songContainer = document.getElementById('song-detail-container');
  if (!songContainer) return;

  const urlParams = new URLSearchParams(window.location.search);
  const songId = parseInt(urlParams.get('id'), 10);
  let lang = urlParams.get('lang') || 'english';
  let subpart = urlParams.get('subpart') || 'script';
  const searchVal = urlParams.get('search') || '';

  if (isNaN(songId)) {
    window.location.href = 'songbook.html';
    return;
  }

  // Find the song array based on language
  let songsArray = [];
  if (lang === 'english') {
    songsArray = SONGBOOK_DATA.english;
  } else {
    songsArray = SONGBOOK_DATA.tamil.script;
  }

  const song = songsArray.find(s => s.id === songId);
  if (!song) {
    window.location.href = 'songbook.html';
    return;
  }

  // Set up back button link with search query state preserved
  const backBtn = document.getElementById('back-to-songbook');
  if (backBtn) {
    backBtn.href = `songbook.html?lang=${lang}&subpart=${subpart}&search=${encodeURIComponent(searchVal)}`;
  }

  const titleElem = document.getElementById('song-detail-title');
  const lyricsElem = document.getElementById('song-detail-lyrics');
  const badgeElem = document.getElementById('song-detail-badge');
  const numberElem = document.getElementById('song-detail-number');

  // Next and Previous sequential song limits
  const totalSongs = songsArray.length;
  const prevId = songId > 1 ? songId - 1 : totalSongs;
  const nextId = songId < totalSongs ? songId + 1 : 1;

  const prevBtn = document.getElementById('prev-song-btn');
  const nextBtn = document.getElementById('next-song-btn');

  if (prevBtn) {
    prevBtn.href = `song.html?id=${prevId}&lang=${lang}&subpart=${subpart}&search=${encodeURIComponent(searchVal)}`;
  }
  if (nextBtn) {
    nextBtn.href = `song.html?id=${nextId}&lang=${lang}&subpart=${subpart}&search=${encodeURIComponent(searchVal)}`;
  }

  function renderSongContent() {
    let titleText = '';
    let lyricsText = '';

    if (lang === 'tamil') {
      badgeElem.textContent = 'தமிழ் பாடல்';
      numberElem.textContent = `பாடல் #${songId}`;
      
      if (subpart === 'script') {
        titleText = song.title;
        lyricsText = song.lyrics;
      } else {
        // Transliterated
        const translitSong = SONGBOOK_DATA.tamil.romanized.find(s => s.id === songId);
        if (translitSong) {
          titleText = translitSong.title;
          lyricsText = translitSong.lyrics;
        } else {
          titleText = song.title;
          lyricsText = song.lyrics;
        }
      }
    } else {
      badgeElem.textContent = 'English Song';
      numberElem.textContent = `Song #${songId}`;
      titleText = song.title;
      lyricsText = song.lyrics;
    }

    titleElem.textContent = titleText;
    lyricsElem.innerHTML = lyricsText.replace(/\n/g, '<br>');

    // Apply Tamil font adjustment for script
    if (lang === 'tamil' && subpart === 'script') {
      songContainer.classList.add('ta-font-adjust');
    } else {
      songContainer.classList.remove('ta-font-adjust');
    }

    // Set page tab title
    document.title = `Church of Christ - Song #${songId}: ${titleText}`;
  }

  // Handle Tamil subpart Script vs Transliterate toggles
  const scriptToggleWrapper = document.getElementById('song-script-toggle-wrapper');
  if (lang === 'tamil') {
    if (scriptToggleWrapper) {
      scriptToggleWrapper.style.display = 'flex';
      const btnScript = document.getElementById('btn-script-tamil');
      const btnRomanized = document.getElementById('btn-script-romanized');

      const updateActiveScriptBtn = () => {
        if (subpart === 'script') {
          btnScript.classList.add('active');
          btnRomanized.classList.remove('active');
        } else {
          btnScript.classList.remove('active');
          btnRomanized.classList.add('active');
        }
      };

      updateActiveScriptBtn();

      btnScript.addEventListener('click', () => {
        subpart = 'script';
        updateActiveScriptBtn();
        const newUrl = new URL(window.location.href);
        newUrl.searchParams.set('subpart', 'script');
        window.history.replaceState({}, '', newUrl);
        
        if (prevBtn) prevBtn.href = `song.html?id=${prevId}&lang=${lang}&subpart=script&search=${encodeURIComponent(searchVal)}`;
        if (nextBtn) nextBtn.href = `song.html?id=${nextId}&lang=${lang}&subpart=script&search=${encodeURIComponent(searchVal)}`;
        if (backBtn) backBtn.href = `songbook.html?lang=${lang}&subpart=script&search=${encodeURIComponent(searchVal)}`;
        
        renderSongContent();
      });

      btnRomanized.addEventListener('click', () => {
        subpart = 'romanized';
        updateActiveScriptBtn();
        const newUrl = new URL(window.location.href);
        newUrl.searchParams.set('subpart', 'romanized');
        window.history.replaceState({}, '', newUrl);
        
        if (prevBtn) prevBtn.href = `song.html?id=${prevId}&lang=${lang}&subpart=romanized&search=${encodeURIComponent(searchVal)}`;
        if (nextBtn) nextBtn.href = `song.html?id=${nextId}&lang=${lang}&subpart=romanized&search=${encodeURIComponent(searchVal)}`;
        if (backBtn) backBtn.href = `songbook.html?lang=${lang}&subpart=romanized&search=${encodeURIComponent(searchVal)}`;
        
        renderSongContent();
      });
    }
  } else {
    if (scriptToggleWrapper) scriptToggleWrapper.style.display = 'none';
  }

  renderSongContent();
}


